import org.springframework.ai.chat.client.ChatClient;
import org.springframework.ai.tool.annotation.Tool;
import org.springframework.ai.tool.annotation.ToolParam;

public class OrderTools {
    private final OrderService orderService;
    public OrderTools(OrderService orderService) { this.orderService = orderService; }

    @Tool(description = "根据订单号查询订单状态和物流信息")
    public OrderInfo queryOrder(@ToolParam(description = "订单号，例如 O20261031001") String orderNo) {
        return orderService.findByNo(orderNo);
    }
}

// 调用（Spring AI 1.x）
String answer = chatClient.prompt()
        .system("你是售后客服，只能通过工具查询订单，不要编造。")
        .user("帮我查一下订单 O20261031001 到哪了")
        .tools(new OrderTools(orderService))
        .call()
        .content();

// Spring AI 1.x：用 MCP Server Starter 把 @Tool 方法暴露为 MCP 工具（示意）
// 依赖：spring-ai-starter-mcp-server-webmvc（或 stdio 版本）
@Service
public class WeatherService {
    @Tool(description = "查询城市当前天气")
    public String weather(@ToolParam(description = "城市名，如 广州") String city) {
        return city + "：多云 26℃";
    }
}

@Configuration
public class McpConfig {
    @Bean
    public ToolCallbackProvider weatherTools(WeatherService weatherService) {
        return MethodToolCallbackProvider.builder().toolObjects(weatherService).build();
    }
}
